BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Goulash hongrois', 'goulash hongrois', 'Hongrie', 'Hongrie',
     'meal', 'soupe-ragoût de bœuf', 'named_traditional_dish', 'warm_aromatic',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation)
  SELECT
    v_family, 3, 'Goulash hongrois', 'Bœuf mijoté longuement dans un bouillon paprikaté avec pommes de terre, tomates et poivrons', ds.id, 'REAL-295',
    'Myko', 'editorial', 8, 30, 180, 'moyenne',
    NULL, NULL,
    'B', 'candidate', 'b75b998965bea176d792b839963257c4',
    '{"sweet":2,"salty":3,"acidic":2,"bitter":1,"umami":4,"heat":2,"pungency":2,"richness":4,"freshness":1,"intensity":4}'::jsonb, ARRAY['paprika doux','oignon fondu','bœuf braisé','tomate cuite']::text[],
    ARRAY['paprika','oignon compoté','bœuf mijoté','tomate cuite']::text[], ARRAY['viande fondante','pomme de terre juste tenue','bouillon rouge lié']::text[],
    ARRAY['Bœuf à braiser cru','Paprika doux','Oignon jaune cru']::text[], ARRAY['Sans paprika doux en quantité — 15 g pour huit, ajoutés hors du feu — ce n''est qu''un ragoût de bœuf : la couleur et le parfum du plat ne viennent de rien d''autre','L''oignon se compte en centaines de grammes, un tiers du poids de la viande, et c''est lui qui lie la sauce','Le paprika brûlé rend le plat amer et rien ne le rattrape : il n''entre jamais sur le feu','Une liaison à la farine ou une base de crème en feraient un paprikás, pas un goulash','Le bouillon reste franchement liquide : la sauce nappe à peine, elle ne se réduit pas en sauce brune']::text[],
    ARRAY['fondue d''oignons','paprika hors du feu','braisage long','mouillement au bouillon','ajout tardif des légumes']::text[], ARRAY['Servi avec des galuska, pâte de farine et d''œufs battus à l''eau salée puis pochée en petits morceaux, comptée à part du ragoût (marmiton, deux versions sur quatre)','Version soupe : viande taillée plus menue, mouillement doublé, carotte et poivron vert ajoutés, une cuillerée de crème fraîche au service (marmiton)','Une demi-cuillerée à café de paprika fort en plus du doux, pour six (marmiton)','Marjolaine séchée mêlée au cumin, à parts égales (marmiton)','À la mijoteuse : 300 g de lard fumé taillé épais, du double concentré de tomate à la place des tomates fraîches, et une liaison farine-fécule de maïs en fin de cuisson (chefsimon)','Finition à la crème fraîche semi-épaisse, 20 cl versés dans la cocotte (chefsimon)','Panachage des poivrons, un rouge et un vert (marmiton)']::text[], ARRAY['lait']::text[],
    'Se garde 3 à 4 jours au réfrigérateur dans un récipient fermé, et gagne à être réchauffé le lendemain — le paprika continue de diffuser dans le bouillon. Se congèle 3 mois, mais en retirant les pommes de terre avant congélation : elles ressortent granuleuses. Réchauffer à couvert et à feu doux en rallongeant d''un peu de bouillon, sans jamais faire rebouillir, ce qui durcirait la viande. Si l''on sert avec de la crème, l''ajouter à l''assiette et non dans la cocotte, pour que le reste se conserve tel quel.', false, '[]'::jsonb,
    NULL, '{}'::jsonb
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
