      ('sensory_contract', '{"profile":"fermented_pungent","scores":{"sweet":1,"salty":5,"acidic":4,"bitter":1,"umami":5,"heat":4,"pungency":5,"richness":3,"freshness":2,"intensity":5},"dominant_flavors":["fermenté","piquant","umami"],"aroma_families":["vin_rouge_réduit","champignon_terreux","laurier","fumé","choucroute","genièvre","pruneau","champignon"],"target_textures":["chou_très_fondant","viandes_tendres","jus_concentré"],"signature_ingredients":["Choucroute crue fermentée","Chou blanc frais","Épaule de porc crue","Saucisse fumée kielbasa"],"identity_guardrails":["choucroute_et_chou_frais","mélange_de_viandes","réchauffages"]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
