  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Dessaler la morue 36 à 48 heures au réfrigérateur dans un grand volume d''eau froide, peau vers le haut, en changeant l''eau cinq à six fois. Goûter une miette avant de cuire : elle doit être franchement salée mais mangeable.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'La veille également, mettre les pois chiches à tremper dans trois fois leur volume d''eau froide.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Égoutter les pois chiches, les cuire 50 à 60 minutes à petits bouillons avec le laurier et la moitié de l''oignon, sans sel. Réserver une louche d''eau de cuisson.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Pocher la morue 8 minutes dans une eau frémissante non salée, jamais bouillante. L''égoutter, retirer peau et arêtes, l''effeuiller en gros pétales.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Dans un plat à four, mêler les pois chiches égouttés, le reste de l''oignon émincé, l''ail en lamelles, la tomate en quartiers et le paprika fumé. Mouiller d''un peu d''eau de cuisson des pois chiches.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Enfourner 20 minutes à 190 °C, puis ajouter les épinards et les pétales de morue, et poursuivre 8 minutes : le poisson doit être juste chaud, pas desséché.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Hors du four, arroser d''huile d''olive crue et de vinaigre de vin rouge, poivrer, couvrir de persil grossièrement haché. Servir tiède.');

