  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Rincer les lentilles corail, les couvrir de trois volumes d’eau avec le curcuma et laisser frémir 15 minutes à découvert jusqu’à ce qu’elles se défassent en purée légère.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Dans une cocotte à sec et bien chaude, blondir l’oignon émincé, ajouter le reste d’ail et de gingembre, la coriandre moulue et le reste de cumin, puis la tomate concassée ; laisser compoter 5 minutes.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Verser les lentilles dans la cocotte, ajouter les épinards par poignées et laisser tomber 5 minutes : le dal palak doit rester coulant, allonger d’un peu d’eau si nécessaire.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Égoutter le poulet de sa marinade et le griller 6 à 7 minutes par face sur une grille très chaude (four position gril ou plancha), jusqu’à ce que les bords soient noircis et le cœur à 75 °C.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
