  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:PROT-007', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('f75af32bc2639e62ed910fc6cac66f2d'::text), 'myko_v3_canonical_recipe'),
