     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation)
  SELECT
    v_family, 3, 'Poulet rôti à la créole et haricots rouges', 'Poulet entier rôti aux épices créoles, accompagné de haricots rouges à la tomate', ds.id, 'PROT-008',
    'Myko', 'editorial', 4, 25, 75, 'moyenne',
    NULL, NULL,
    'B', 'candidate', '6d8d9c6e7d5bbd1f796ed2fd412926cf',
    '{"sweet":2,"salty":3,"acidic":2,"bitter":1,"umami":4,"heat":3,"pungency":3,"richness":3,"freshness":2,"intensity":4}'::jsonb, ARRAY['paprika fumé','poivron','haricot rouge']::text[],
