     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation)
  SELECT
    v_family, 3, 'Jarret de bœuf braisé aux lentilles vertes et aux épinards, moutarde et thym', 'Jarret de bœuf braisé au vin blanc avec lentilles vertes et épinards, lié à la moutarde en fin de cuisson', ds.id, 'PROT-009',
    'Myko', 'editorial', 4, 30, 165, 'moyenne',
    NULL, NULL,
    'B', 'candidate', 'a2f7dc31c410c1d60ebbb6db28dd93b4',
    '{"sweet":1,"salty":3,"acidic":2,"bitter":1,"umami":5,"heat":0,"pungency":3,"richness":3,"freshness":2,"intensity":4}'::jsonb, ARRAY['umami','terreux','rôti','herbacé']::text[],
    ARRAY['bœuf','oignon_compoté','thym','laurier','moutarde','champignon_terreux']::text[], ARRAY['viande_fondante','légumes_tendres','sauce_courte']::text[],
    ARRAY['Jarret de bœuf cru, avec os','Lentille verte sèche, crue','Moutarde de Dijon','Épinard frais']::text[], ARRAY['conserver_les_ingrédients_signatures','conserver_la_technique_centrale','ne_pas_remplacer_par_un_simple_équivalent_nutritionnel','cuisson_longue','pas_de_crème','lentilles_cuites_dans_le_braisage']::text[],
    ARRAY['saisie à sec','déglaçage','braisage','cuisson des légumineuses dans le braisage','liaison à la moutarde hors du feu']::text[], ARRAY['Lentilles corail à la place des vertes pour une texture plus liée','Chou frisé à la place des épinards','Version cocotte-minute : 45 min sous pression puis 15 min lentilles']::text[], ARRAY['moutarde']::text[],
    '4 jours au réfrigérateur ; 3 mois au congélateur sans les épinards (les ajouter au réchauffage). Meilleur le lendemain, le jus prend en gelée grâce au collagène du jarret.', false, '[]'::jsonb,
    NULL, '{}'::jsonb
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
