  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:SRC-002', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('dd1f77e6d79eb637e0de29320f5b5975'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"warm_aromatic","scores":{"sweet":1,"salty":2,"acidic":0,"bitter":0,"umami":1,"heat":3,"pungency":0,"richness":2,"freshness":4,"intensity":1},"dominant_flavors":["bœuf_braisé","carotte_fondante","vin_blanc"],"aroma_families":["viande_braisée","oignon_compoté","bouillon_corsé"],"target_textures":["viande_effilochable","sauce_nappante","carotte_fondante"],"signature_ingredients":["Bœuf à braiser cru","Carotte crue","Vin blanc sec"],"identity_guardrails":["Les carottes cuisent avec la viande et deviennent fondantes : les ajouter tard en ferait une garniture, pas un bœuf mode.","La quantité de carottes égale au moins la moitié du poids de viande."]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
