  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Les égoutter, les couvrir d''eau froide avec l''oignon entier, le thym et le laurier, porter à frémissement et cuire une heure à petits bouillons. Ne saler qu''en fin de cuisson, le sel précoce raidit la peau.');

