  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:SRC-003', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('7469762de7d5da4e8d9a1b1b05b239c5'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"warm_aromatic","scores":{"sweet":1,"salty":2,"acidic":0,"bitter":0,"umami":0,"heat":3,"pungency":0,"richness":3,"freshness":5,"intensity":1},"dominant_flavors":["agneau_rôti","ail_confit","haricot_fondant"],"aroma_families":["viande_rôtie","ail","thym"],"target_textures":["croûte_dorée","chair_rosée","haricot_fondant"],"signature_ingredients":["Gigot d''agneau cru","Haricot flageolet sec","Ail cru"],"identity_guardrails":["Le gigot repose avant d''être tranché, sinon le jus part sur la planche.","Les flageolets ne sont pas un accompagnement rapporté : ils finissent dans le jus de rôtissage."]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '349fe655173914ccfd579fd2e6d29046' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
