  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Langue de boeuf sauce piquante', 'langue de boeuf sauce piquante', 'France', 'France',
     'meal', 'plat mijoté', 'named_traditional_dish', 'bright_acidic',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation)
  SELECT
    v_family, 3, 'Langue de boeuf sauce piquante', 'Langue de bœuf pochée longuement dans un court-bouillon, servie avec une sauce au vinaigre et cornichons', ds.id, 'SRC-013',
    'Myko', 'editorial', 6, 35, 165, 'moyenne',
    NULL, NULL,
    'B', 'candidate', '46686993371eb19b25a76e3f71b78ec8',
    '{"sweet":1,"salty":3,"acidic":4,"bitter":1,"umami":4,"heat":0,"pungency":3,"richness":3,"freshness":2,"intensity":4}'::jsonb, ARRAY['acidité vinaigrée','umami de bouillon de bœuf','cornichon saumuré','aromates de court-bouillon']::text[],
    ARRAY['vinaigré','épices chaudes','herbacé']::text[], ARRAY['viande fondante','sauce nappante','éclats croquants de cornichon']::text[],
    ARRAY['Langue de bœuf crue','Cornichon au vinaigre','Vinaigre blanc']::text[], ARRAY['Sans langue de bœuf pochée puis pelée, le plat n''existe plus : aucune autre pièce de bœuf ne peut s''y substituer.','Sans l''acidité conjointe du vinaigre réduit et des cornichons, la sauce n''est plus piquante mais une simple sauce brune.','La sauce doit être liée au roux avec le bouillon de cuisson de la langue, et non avec un fond étranger : c''est ce recyclage qui fait sa profondeur.']::text[],
    ARRAY['blanchiment','pochage','réduction','déglaçage','mijotage']::text[], ARRAY['Remplacer le vinaigre blanc de la sauce par du vinaigre de vin rouge, pour une acidité plus ronde et une couleur plus soutenue.','Version tomatée du Sud : doubler le concentré de tomate, ajouter une pointe de piment et servir la sauce plus courte, sans roux.','Cuisson accélérée en autocuiseur : quarante-cinq minutes sous pression après le blanchiment, le bouillon restant utilisé de la même façon pour la sauce.']::text[], ARRAY['gluten','lait','sulfites']::text[],
    'Se garde 3 jours au réfrigérateur entre 0 et 4 °C, tranches immergées dans la sauce ou dans un peu de bouillon filtré pour éviter le dessèchement. Réchauffer à feu doux sans ébullition. La congélation est possible 2 mois pour la viande et sa sauce ensemble, mais la sauce liée à la farine peut se déphaser : la relier au fouet à la remise en température, et ne jamais congeler les cornichons, à ajouter au dernier moment.', false, '[]'::jsonb,
    NULL, '{}'::jsonb
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
