  VALUES (v_version, 1, 'Réunir dans un saladier la farine, la levure chimique et le sel fin, creuser un creux au centre, y verser l''eau tiède et 15 g d''huile d''olive, puis travailler à la main jusqu''à obtenir une boule souple et lisse qui se décolle des doigts ; couvrir d''un linge et réserver le temps de cuire la garniture.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Peler les oignons et les tailler en lamelles fines et régulières. Chauffer le reste de l''huile d''olive dans une grande sauteuse, y verser les oignons avec le sucre semoule, le thym séché, les herbes de Provence et le poivre noir moulu.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Couvrir et laisser compoter sur feu très doux environ 35 minutes en remuant toutes les cinq minutes ; ajouter l''ail écrasé à mi-cuisson. Les oignons doivent devenir translucides et fondants, à peine blonds, sans jamais colorer ni accrocher — une cuillère d''eau suffit à rattraper le fond si besoin. Ne pas saler à cette étape.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Hors du feu, écraser les deux tiers des anchois égouttés dans les oignons encore chauds jusqu''à ce qu''ils se délitent entièrement dans la compotée ; réserver le tiers restant en filets entiers pour le dessus, puis laisser tiédir la garniture.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Préchauffer le four à 220 °C. Étaler la pâte au rouleau en un rectangle d''environ 40 × 25 cm sur une plaque tapissée de papier cuisson, en laissant un léger bourrelet tout autour pour retenir la garniture.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Répartir la compotée d''oignons en couche régulière jusqu''au bourrelet, croiser dessus les filets d''anchois réservés de façon à dessiner des losanges, et déposer une olive noire au creux de chaque losange.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Enfourner environ 20 minutes, jusqu''à ce que le pourtour soit doré et le dessous de la pâte sec et ferme au toucher. Sortir la plaque, laisser reposer une dizaine de minutes et servir tiède ou à température ambiante, jamais brûlante.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'SRC-019', 'recipe_family', 'Pissaladière',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'SRC-019', 'missing_required_count', v_missing), 'open');
  END IF;

  WITH axis AS (
    INSERT INTO culinary.recipe_variation_axes
      (recipe_family_id, name, selection_mode, required)
    VALUES (v_family, 'Variante culinaire', 'single', false)
    RETURNING id
  )
  INSERT INTO culinary.recipe_variation_options
    (variation_axis_id, name, confidence_level, status)
  SELECT axis.id, variant.name, 'B', 'candidate'
  FROM axis
  CROSS JOIN unnest(ARRAY['Pichade mentonnaise : ajouter aux oignons des tomates pelées concassées et laisser réduire une heure avant de garnir la pâte.','Version aux olives vertes dénoyautées, plus douce et moins amère que l''olive noire.','Pissaladière au fenouil : remplacer un tiers des oignons par du fenouil émincé compoté avec eux.','Base à l''aubergine rôtie écrasée mêlée aux oignons, pour une garniture plus fondante.']::text[]) AS variant(name);

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_validation', 5,
     ARRAY['source_backed_variant_needs_test'], '{"recipe_code":"SRC-019","variants":["Pichade mentonnaise : ajouter aux oignons des tomates pelées concassées et laisser réduire une heure avant de garnir la pâte.","Version aux olives vertes dénoyautées, plus douce et moins amère que l''olive noire.","Pissaladière au fenouil : remplacer un tiers des oignons par du fenouil émincé compoté avec eux.","Base à l''aubergine rôtie écrasée mêlée aux oignons, pour une garniture plus fondante."]}'::jsonb, 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:SRC-019', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('0919928516b3b809b0badd6ec111fb20'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"savory_crisp","scores":{"sweet":3,"salty":4,"acidic":1,"bitter":1,"umami":4,"heat":0,"pungency":1,"richness":3,"freshness":1,"intensity":4},"dominant_flavors":["oignon confit sucré","anchois salé","olive noire","huile d''olive"],"aroma_families":["allium","herbacé","marin"],"target_textures":["oignon fondant","croûte croustillante","filet d''anchois moelleux"],"signature_ingredients":["Oignon jaune cru","Anchois à l''huile, égoutté","Olive noire"],"identity_guardrails":["Sans anchois, ce n''est plus une pissaladière mais une simple tarte à l''oignon.","Les oignons doivent compoter longuement à feu doux jusqu''à fondre : simplement sautés, ils perdent la douceur qui fait le plat.","Ni tomate ni fromage : la version tomatée est une pichade mentonnaise, un autre plat.","La base est une pâte à pain fine, pas une pâte feuilletée ni une pâte brisée."]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '349fe655173914ccfd579fd2e6d29046' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;
DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Poireaux gratinés à la béchamel', 'poireaux gratines a la bechamel', 'France', 'France',
     'meal', 'gratin', 'domestic_standard', 'creamy_savory',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation)
  SELECT
    v_family, 3, 'Poireaux gratinés à la béchamel', 'Poireaux blanchis gratinés sous une couche de crème fraîche et gruyère', ds.id, 'SRC-020',
    'Myko', 'editorial', 4, 25, 35, 'facile',
    NULL, NULL,
    'B', 'candidate', '76b58a18a19452f35a033acad577b657',
    '{"sweet":2,"salty":3,"acidic":0,"bitter":1,"umami":3,"heat":0,"pungency":1,"richness":4,"freshness":1,"intensity":3}'::jsonb, ARRAY['poireau doux','crème lactée','fromage gratiné']::text[],
    ARRAY['lactée','alliacée','grillée']::text[], ARRAY['fondant','croûte gratinée','nappage crémeux']::text[],
    ARRAY['Poireau cru','Gruyère râpé','Crème fraîche liquide entière']::text[], ARRAY['Le poireau doit être précuit puis pressé : sans cet égouttage, le plat rend son eau et devient une soupe gratinée.','Sans gruyère râpé sur le dessus, il n''y a plus de croûte dorée et le plat cesse d''être un gratin.','Le liant blanc et onctueux est obligatoire : privé de crème, l''appareil n''est plus qu''un plat de poireaux rôtis.']::text[],
    ARRAY['blanchiment','gratinage']::text[], ARRAY['Version béchamel classique : remplacer la crème par une sauce blanche montée au roux beurre-farine-lait, muscadée, dès que ces formes sont disponibles au catalogue.','Montage à la tomate façon marmiton.org : alterner des couches de tomates pelées et épépinées mijotées à l''oignon et à l''ail avec les poireaux et le fromage.','Finition croustillante : parsemer de chapelure avant le passage au four pour une croûte plus sèche et plus craquante.','Portions individuelles : répartir en ramequins et gratiner huit à dix minutes seulement, comme le fait 750g.com.','Cuisson vapeur : passer les tronçons cinq minutes au panier vapeur au lieu de l''eau bouillante, pour un poireau moins gorgé d''eau.']::text[], ARRAY['lait']::text[],
    'Se conserve 3 jours au réfrigérateur entre 0 et 4 °C, couvert une fois complètement refroidi, et se réchauffe 15 minutes à 180 °C pour retrouver la croûte. La congélation est déconseillée : le poireau relâche son eau à la décongélation et la crème risque de trancher.', false, '[]'::jsonb,
    NULL, '{}'::jsonb
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation
  RETURNING id INTO v_version;

  DELETE FROM quality.review_tasks rt
  USING culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version
    AND rt.entity_type = 'recipe_ingredient_requirement'
    AND rt.entity_id = req.id;
  DELETE FROM quality.review_tasks WHERE entity_type = 'recipe_version' AND entity_id = v_version;
  DELETE FROM culinary.recipe_steps WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_ingredient_requirements WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_instruction_branches WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_components WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_variation_axes WHERE recipe_family_id = v_family;

  INSERT INTO culinary.recipe_components (recipe_version_id, name, component_role, position)
  VALUES (v_version, 'plat', 'main', 1)
  RETURNING id INTO v_component;

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
