       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'SRC-020', 'missing_required_count', v_missing), 'open');
  END IF;

  WITH axis AS (
    INSERT INTO culinary.recipe_variation_axes
      (recipe_family_id, name, selection_mode, required)
    VALUES (v_family, 'Variante culinaire', 'single', false)
    RETURNING id
  )
  INSERT INTO culinary.recipe_variation_options
    (variation_axis_id, name, confidence_level, status)
  SELECT axis.id, variant.name, 'B', 'candidate'
  FROM axis
  CROSS JOIN unnest(ARRAY['Version béchamel classique : remplacer la crème par une sauce blanche montée au roux beurre-farine-lait, muscadée, dès que ces formes sont disponibles au catalogue.','Montage à la tomate façon marmiton.org : alterner des couches de tomates pelées et épépinées mijotées à l''oignon et à l''ail avec les poireaux et le fromage.','Finition croustillante : parsemer de chapelure avant le passage au four pour une croûte plus sèche et plus craquante.','Portions individuelles : répartir en ramequins et gratiner huit à dix minutes seulement, comme le fait 750g.com.','Cuisson vapeur : passer les tronçons cinq minutes au panier vapeur au lieu de l''eau bouillante, pour un poireau moins gorgé d''eau.']::text[]) AS variant(name);

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_validation', 5,
     ARRAY['source_backed_variant_needs_test'], '{"recipe_code":"SRC-020","variants":["Version béchamel classique : remplacer la crème par une sauce blanche montée au roux beurre-farine-lait, muscadée, dès que ces formes sont disponibles au catalogue.","Montage à la tomate façon marmiton.org : alterner des couches de tomates pelées et épépinées mijotées à l''oignon et à l''ail avec les poireaux et le fromage.","Finition croustillante : parsemer de chapelure avant le passage au four pour une croûte plus sèche et plus craquante.","Portions individuelles : répartir en ramequins et gratiner huit à dix minutes seulement, comme le fait 750g.com.","Cuisson vapeur : passer les tronçons cinq minutes au panier vapeur au lieu de l''eau bouillante, pour un poireau moins gorgé d''eau."]}'::jsonb, 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:SRC-020', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('76b58a18a19452f35a033acad577b657'::text), 'myko_v3_canonical_recipe'),
