  SELECT
    v_family, 3, 'Poivrons farcis au riz', 'Poivrons rouges blanchis farcis de riz, lardons et tomate liés à l''œuf, rôtis au four', ds.id, 'SRC-021',
    'Myko', 'editorial', 4, 25, 40, 'facile',
