  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation)
  SELECT
    v_family, 3, 'Riz cantonais', 'Riz sauté à la poêle avec œufs brouillés, jambon blanc et petits pois', ds.id, 'SRC-023',
    'Myko', 'editorial', 4, 15, 20, 'facile',
    NULL, NULL,
    'B', 'candidate', '133e3944eb013dedc89f06acf64f09c2',
    '{"sweet":1,"salty":3,"acidic":0,"bitter":0,"umami":3,"heat":0,"pungency":1,"richness":2,"freshness":1,"intensity":2}'::jsonb, ARRAY['salé','umami','douceur végétale']::text[],
    ARRAY['alliacé','grillé','céréalier']::text[], ARRAY['grains détachés','moelleux','lanières fondantes']::text[],
    ARRAY['Riz cru','Œuf cru','Jambon blanc cuit','Petit pois surgelé']::text[], ARRAY['L''œuf doit être cuit à part en omelette fine puis retaillé en lanières : des œufs brouillés directement dans le riz donnent un autre plat.','Le riz doit être cuit à l''avance et refroidi avant d''être sauté ; un riz encore chaud colle et fait perdre la texture en grains détachés qui définit le plat.','Le trio riz, œuf et petit pois est présent dans les sept sources du dossier : retirer l''un des trois fait sortir de l''identité du riz cantonais.','Le sauté se fait sur feu vif et court, jamais en mijotage : le plat n''est pas un riz cuisiné en sauce.']::text[],
    ARRAY['saisie','blanchiment']::text[], ARRAY['Version aux crevettes : remplacer tout ou partie du jambon blanc par des crevettes décortiquées jetées trente secondes dans le wok très chaud avant les légumes.','Version végétarienne : supprimer le jambon, doubler la dose de petit pois et de carotte, et relever d''un trait supplémentaire de sauce soja.','Version aux lardons, courante chez marmiton.org : substituer des lardons fumés au jambon blanc et les faire rendre leur gras avant d''ajouter l''huile.','Riz sauté beurré à la façon de chefsimon.com : brouiller les œufs à la spatule dans le beurre au lieu de dresser une omelette, et les réincorporer en fin de sauté.']::text[], ARRAY['œuf','lait','gluten','soja','sésame']::text[],
    'Se garde 2 jours au réfrigérateur entre 0 et 4 °C dans une boîte hermétique, à refroidir rapidement après cuisson car le riz cuit tiède est un terrain favorable à Bacillus cereus. Réchauffer à la poêle bien chaude, jamais tiède. La congélation est possible 1 mois mais dégrade nettement la texture : les petits pois rendent de l''eau et l''omelette devient caoutchouteuse — décongeler au réfrigérateur puis sauter à feu vif.', false, '[]'::jsonb,
    NULL, '{}'::jsonb
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
