  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Passer le riz sous l''eau claire en le brassant à la main jusqu''à ce que l''eau ressorte limpide, puis le mettre dans une casserole avec une fois et demie son volume d''eau salée. Porter à frémissement, couvrir, baisser au minimum et laisser boire tout le liquide sans jamais soulever le couvercle.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Laisser gonfler dix minutes hors du feu, toujours couvert, puis étaler le riz en couche mince sur un grand plat pour qu''il tiédisse et que les grains cessent de coller entre eux. Un riz refroidi tient le sauté ; un riz brûlant se transforme en purée.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Pendant ce temps, ébouillanter les petits pois deux minutes puis les égoutter et les rafraîchir sous l''eau froide. Tailler l''oignon en petits dés, hacher l''ail au couteau, débiter la carotte en brunoise fine et couper le jambon en cubes de la taille d''un pois.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Fouetter les œufs avec une pincée de sel et un tour de moulin. Les verser dans une poêle chaude où le beurre a juste fondu, incliner le manche pour étaler une galette très mince, la décoller dès qu''elle est prise, la faire glisser sur une planche, la rouler sur elle-même et la trancher en fines lanières.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Faire fumer l''huile d''olive dans un wok ou une grande sauteuse, y jeter oignon, ail et carotte, et les remuer sans arrêt deux à trois minutes : ils doivent s''assouplir en gardant leur teinte claire, sans jamais roussir.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Ajouter le jambon et les petits pois, sauter une minute pour les enrober de matière grasse, puis verser le riz refroidi en l''écrasant du dos de la spatule pour séparer les paquets de grains. Étaler le tout contre les parois chaudes et laisser accrocher quelques secondes entre deux mouvements.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Disperser les lanières d''omelette, arroser de sauce soja versée en pluie sur le bord brûlant du wok, ajouter l''huile de sésame hors du feu, goûter puis rectifier en sel et en poivre. Sauter une dernière minute et envoyer immédiatement, tant que la vapeur monte.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'SRC-023', 'recipe_family', 'Riz cantonais',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'SRC-023', 'missing_required_count', v_missing), 'open');
  END IF;

