  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Porter un grand volume d''eau salée à ébullition, y jeter le riz cru en pluie et le laisser cuire à découvert et à frémissement une quinzaine de minutes, jusqu''à ce que le grain cède sous la dent en gardant un cœur ferme.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Cuire les œufs dix minutes à l''eau frémissante, les rafraîchir, les écaler et les couper en quartiers.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Verser le riz dans une passoire, le rincer sous un filet d''eau froide en remuant à la main jusqu''à ce qu''il ne soit plus tiède du tout, puis le laisser s''égoutter une dizaine de minutes pour qu''il perde son excès d''eau.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Pendant la cuisson, fendre le poivron vert frais, en ôter le pédoncule, les graines et les cloisons blanches, puis le détailler en petits dés réguliers de la taille d''un grain de maïs, sans le cuire.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Réunir la tomate râpée et son jus dans un bol, la saler, patienter cinq minutes le temps qu''elle rende son eau, puis verser l''huile d''olive vierge extra en filet en fouettant pour obtenir un assaisonnement lié et brillant.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Rassembler dans un saladier le riz bien refroidi et les dés de poivron, napper de l''assaisonnement à la tomate, donner un tour de poivre noir moulu et mélanger à la fourchette en soulevant la masse pour détacher les grains sans les écraser.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Goûter, rectifier en sel et en poivre, couvrir puis réserver au moins trente minutes au réfrigérateur afin que le riz s''imprègne, et remuer une dernière fois juste avant de servir bien frais.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'SRC-024', 'recipe_family', 'Salade de riz niçoise',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'SRC-024', 'missing_required_count', v_missing), 'open');
  END IF;

  WITH axis AS (
    INSERT INTO culinary.recipe_variation_axes
      (recipe_family_id, name, selection_mode, required)
    VALUES (v_family, 'Variante culinaire', 'single', false)
    RETURNING id
  )
  INSERT INTO culinary.recipe_variation_options
    (variation_axis_id, name, confidence_level, status)
  SELECT axis.id, variant.name, 'B', 'candidate'
  FROM axis
  CROSS JOIN unnest(ARRAY['Remplacer un tiers du riz blanc par du riz complet pour un grain plus mordant, en allongeant la cuisson de cinq à sept minutes.','Plonger les dés de poivron vert une minute dans l''eau bouillante puis les refroidir aussitôt, pour une version plus digeste tout en gardant du croquant.','Servir le riz encore tiède simplement arrosé de l''assaisonnement à la tomate, en accompagnement d''un poisson grillé.']::text[]) AS variant(name);

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_validation', 5,
     ARRAY['source_backed_variant_needs_test'], '{"recipe_code":"SRC-024","variants":["Remplacer un tiers du riz blanc par du riz complet pour un grain plus mordant, en allongeant la cuisson de cinq à sept minutes.","Plonger les dés de poivron vert une minute dans l''eau bouillante puis les refroidir aussitôt, pour une version plus digeste tout en gardant du croquant.","Servir le riz encore tiède simplement arrosé de l''assaisonnement à la tomate, en accompagnement d''un poisson grillé."]}'::jsonb, 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:SRC-024', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('13325c5ea44bd22d46bfc363cc2a5d18'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"bright_acidic","scores":{"sweet":1,"salty":2,"acidic":3,"bitter":1,"umami":2,"heat":0,"pungency":1,"richness":3,"freshness":4,"intensity":2},"dominant_flavors":["tomate","huile d''olive","poivron vert"],"aroma_families":["végétal","fruité"],"target_textures":["grains de riz détachés","dés de poivron croquants","enrobage huileux léger"],"signature_ingredients":["Thon au naturel en conserve, égoutté","Riz cru","Huile d''olive vierge extra"],"identity_guardrails":["Sans thon ni œuf dur, ce n''est plus une salade niçoise mais une salade de riz aux crudités.","Le riz est refroidi avant d''être assaisonné : tiède, il boit l''huile et devient pâteux.","Les légumes restent crus et taillés à la main ; cuits, la salade perd son mordant."]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '349fe655173914ccfd579fd2e6d29046' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;
DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Salade piémontaise', 'salade piemontaise', 'France', 'France',
     'meal', 'salade composée', 'named_traditional_dish', 'creamy_savory',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation)
  SELECT
    v_family, 3, 'Salade piémontaise', 'Pommes de terre en rondelles avec jambon blanc, œufs durs, cornichons et mayonnaise moutardée', ds.id, 'SRC-025',
    'Myko', 'editorial', 4, 25, 25, 'facile',
    NULL, NULL,
    'B', 'candidate', '6767ca05e39ddcac7d138a7bbab36328',
    '{"sweet":1,"salty":3,"acidic":3,"bitter":0,"umami":2,"heat":0,"pungency":2,"richness":4,"freshness":3,"intensity":3}'::jsonb, ARRAY['acidulé','salé','moutardé','crémeux']::text[],
    ARRAY['vinaigré','herbacé','végétal frais']::text[], ARRAY['fondant','croquant','crémeux']::text[],
    ARRAY['Pomme de terre cuite','Mayonnaise','Cornichon au vinaigre','Œuf dur']::text[], ARRAY['Sans dés de pomme de terre cuite refroidis, ce n''est plus une salade piémontaise mais une simple salade de crudités.','La sauce doit rester à dominante mayonnaise : remplacée par une vinaigrette seule, le plat perd son onctuosité caractéristique.','L''acidité vive apportée par les cornichons et le vinaigre est constitutive du plat ; sans elle, l''ensemble devient plat et gras.','Le plat se sert froid après repos au réfrigérateur : servi tiède, il n''est pas reconnaissable.']::text[],
    ARRAY['pochage','émulsion']::text[], ARRAY['Sauce maison : monter une mayonnaise au jaune d''œuf, à la moutarde de Dijon et à l''huile d''olive vierge extra, puis la détendre au vinaigre plutôt que d''utiliser une mayonnaise du commerce.','Version allégée : remplacer une partie de la mayonnaise par de la crème fraîche liquide entière relevée de moutarde, pour une sauce plus fluide et moins riche.','Sans porc : substituer au jambon blanc des blancs de volaille cuits taillés en dés, comme le proposent certaines sources du dossier.','Version végétarienne : supprimer le jambon et doubler la part d''œuf dur, en renforçant le croquant avec davantage de cornichons.']::text[], ARRAY['œuf','moutarde','lait','sulfites']::text[],
    'Se conserve 48 heures maximum au réfrigérateur entre 0 et 4 °C, dans un contenant hermétique, en raison de la mayonnaise et de l''œuf dur. Sortir 10 minutes avant de servir. Ne se congèle pas : la mayonnaise se déphase et la pomme de terre devient farineuse et granuleuse à la décongélation.', false, '[]'::jsonb,
    NULL, '{}'::jsonb
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation
  RETURNING id INTO v_version;

  DELETE FROM quality.review_tasks rt
