  SELECT
    v_family, 3, 'Sauté de porc aux pruneaux', 'Épaule de porc saisie puis mijotée avec des pruneaux et des lardons fumés', ds.id, 'SRC-026',
    'Myko', 'editorial', 4, 20, 90, 'facile',
