  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Parez l''épaule de veau et taillez-la en cubes réguliers d''environ quatre centimètres, puis roulez-les dans la farine et secouez-les pour ne garder qu''un voile mince.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Portez une petite casserole d''eau à frémissement, immergez-y les olives vertes et noires une quinzaine de secondes pour adoucir la saumure, égouttez-les et gardez-les de côté.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Chauffez l''huile d''olive dans une cocotte à fond épais et colorez les cubes de veau par petites poignées, sans jamais surcharger le fond, jusqu''à une croûte ambrée sur toutes les faces ; débarrassez la viande et faites rendre leur gras aux lardons au même endroit.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Baissez le feu, jetez l''oignon finement émincé et la carotte en rondelles dans la graisse de cuisson, laissez-les fondre sans brunir, ajoutez l''ail écrasé puis le concentré de tomate et tournez deux minutes pour qu''il perde son mordant.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Mouillez avec le vin blanc en raclant les sucs collés au fond à la spatule, laissez-le réduire de moitié, remettez la viande et les lardons, versez l''eau à hauteur, parsemez de thym et de romarin, salez et poivrez.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Couvrez et maintenez un frémissement à peine perceptible pendant une heure et quart, en remuant délicatement de loin en loin pour que rien n''attache.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Ajoutez les olives égouttées, retirez le couvercle et prolongez trente minutes : la viande doit céder sous la fourchette et la sauce napper le dos d''une cuillère. Goûtez et rectifiez le sel en tenant compte des olives avant d''envoyer à table.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'SRC-027', 'recipe_family', 'Sauté de veau aux olives',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'SRC-027', 'missing_required_count', v_missing), 'open');
  END IF;

