  VALUES (v_version, 1, 'Passer les olives noires dénoyautées sous un filet d''eau froide, les égoutter puis les éponger dans un linge propre afin de retirer l''excédent de saumure qui rendrait la pâte trop salée.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Peler l''ail, ouvrir la gousse en deux et ôter le germe central s''il a verdi, puis la débiter en petits éclats pour qu''elle se disperse régulièrement dans la préparation.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Réunir les olives et l''ail dans la cuve d''un robot, puis travailler par impulsions brèves en raclant les parois entre chacune, jusqu''à un hachis encore perceptible sous la dent.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Relancer le moteur à petite vitesse et laisser couler l''huile d''olive en un mince ruban continu : la masse se lie peu à peu et prend un aspect luisant et souple.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Poivrer, goûter avant toute chose, puis n''ajouter le sel que par très petites touches, les olives en apportant déjà une large part.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Débarrasser dans un bocal, tasser à la cuillère pour chasser les bulles d''air, napper d''un voile d''huile et laisser reposer au frais une heure au moins avant de tartiner.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'SRC-030', 'recipe_family', 'Tapenade noire',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'SRC-030', 'missing_required_count', v_missing), 'open');
  END IF;

  WITH axis AS (
    INSERT INTO culinary.recipe_variation_axes
      (recipe_family_id, name, selection_mode, required)
    VALUES (v_family, 'Variante culinaire', 'single', false)
    RETURNING id
  )
  INSERT INTO culinary.recipe_variation_options
    (variation_axis_id, name, confidence_level, status)
  SELECT axis.id, variant.name, 'B', 'candidate'
  FROM axis
  CROSS JOIN unnest(ARRAY['Version rustique entièrement au couteau, sans robot, pour conserver des éclats d''olive nettement visibles et une mâche plus franche.','Ail adouci : le plonger deux minutes dans l''eau bouillante avant de le mixer, ce qui efface sa pointe la plus mordante.','Emploi en farce : glisser une cuillerée dans le ventre d''un poisson entier avant passage au four, la pâte parfumant la chair pendant la cuisson.','Emploi en tarte salée : étaler une fine couche sur un fond de pâte garni de tomates confites avant enfournement.']::text[]) AS variant(name);

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_validation', 5,
     ARRAY['source_backed_variant_needs_test'], '{"recipe_code":"SRC-030","variants":["Version rustique entièrement au couteau, sans robot, pour conserver des éclats d''olive nettement visibles et une mâche plus franche.","Ail adouci : le plonger deux minutes dans l''eau bouillante avant de le mixer, ce qui efface sa pointe la plus mordante.","Emploi en farce : glisser une cuillerée dans le ventre d''un poisson entier avant passage au four, la pâte parfumant la chair pendant la cuisson.","Emploi en tarte salée : étaler une fine couche sur un fond de pâte garni de tomates confites avant enfournement."]}'::jsonb, 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:SRC-030', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('40a21cf03b3b4dc803dfea925d3abdf6'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"warm_aromatic","scores":{"sweet":0,"salty":4,"acidic":2,"bitter":2,"umami":4,"heat":0,"pungency":2,"richness":4,"freshness":1,"intensity":4},"dominant_flavors":["olive noire","ail cru","huile d''olive"],"aroma_families":["fruité vert","alliacé","saumuré"],"target_textures":["pâte granuleuse","onctueux"],"signature_ingredients":["Olive noire dénoyautée","Huile d''olive vierge extra"],"identity_guardrails":["Sans Olive noire dénoyautée en base largement majoritaire, ce n''est plus une tapenade noire mais une autre tartinade.","L''Huile d''olive vierge extra est le seul liant : un corps gras neutre, du beurre ou de la crème effacerait l''identité provençale.","La préparation se monte entièrement à cru : cuire les olives détruirait le profil fruité et amer recherché.","La texture doit rester granuleuse : mixée jusqu''à la purée lisse, la tapenade perd son grain caractéristique."]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '349fe655173914ccfd579fd2e6d29046' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;
DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Aubergines farcies', 'aubergines farcies', 'France', 'France',
     'meal', 'plat au four', 'named_traditional_dish', 'savory_tomato',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation)
  SELECT
    v_family, 3, 'Aubergines farcies', 'Aubergines évidées farcies de bœuf haché à la tomate et à l''ail, gratinées au gruyère', ds.id, 'SRC-031',
    'Myko', 'editorial', 4, 25, 50, 'facile',
    NULL, NULL,
    'B', 'candidate', 'c194b466759ecc285cca6bbb934d32e0',
    '{"sweet":2,"salty":3,"acidic":2,"bitter":1,"umami":4,"heat":0,"pungency":2,"richness":3,"freshness":2,"intensity":3}'::jsonb, ARRAY['tomate cuite','viande rôtie','ail']::text[],
    ARRAY['herbacé','alliacé','fromager']::text[], ARRAY['chair fondante','farce moelleuse','surface gratinée']::text[],
    ARRAY['Aubergine fraîche','Bœuf haché cru 15 % MG','Tomate râpée']::text[], ARRAY['La coque d''aubergine rôtie doit rester le contenant : servie en gratin dans un plat, la préparation redevient une simple sauce à la viande.','La chair prélevée retourne obligatoirement dans la farce ; la jeter fait perdre au plat son goût d''aubergine et son moelleux.','La farce se lie à la tomate réduite et à l''œuf, jamais à une béchamel, qui la ferait basculer vers la moussaka.']::text[],
    ARRAY['rôtissage','saisie','réduction','gratinage']::text[], ARRAY['Sans viande : remplacer le bœuf haché par du riz cuit et doubler le Gruyère râpé, comme sur la version au jambon et au comté de 750g.com.','Version crémeuse : napper la farce d''un filet de Crème fraîche liquide entière juste avant le passage au gratin.','Cuisson en air fryer : 30 minutes à 180 °C pour les coques, puis 8 minutes une fois garnies et fromagées (chefsimon.com).','Sans œuf : supprimer le liant et prolonger la réduction de 5 minutes, la tomate assurant seule la tenue de la farce.']::text[], ARRAY['lait','œuf']::text[],
    'Trois jours au réfrigérateur à 4 °C dans une boîte fermée ; réchauffer 15 minutes à 160 °C plutôt qu''au micro-ondes, qui détrempe la croûte. Congélation possible deux mois avant gratinage, mais la coque rend beaucoup d''eau à la décongélation et perd sa tenue.', false, '[]'::jsonb,
    NULL, '{}'::jsonb
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation
  RETURNING id INTO v_version;

  DELETE FROM quality.review_tasks rt
  USING culinary.recipe_ingredient_requirements req
