  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Compter 1,25 kg de moules en coquille chez le poissonnier : c''est le poids d''achat qui donne les 375 g de chair annoncés. Les gratter, tirer le byssus, les rincer à grande eau froide et jeter sans hésiter toute coquille fêlée ou qui refuse de se refermer lorsqu''on la tapote.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Verser le vin blanc dans un faitout, y jeter les moules, couvrir et monter à feu vif quatre à cinq minutes en secouant une fois la casserole. Les retirer dès qu''elles bâillent, décoquiller les trois quarts et garder le reste en coquille pour le service. Filtrer le jus rendu à travers une passoire doublée d''un linge : c''est lui qui apportera le sel et l''iode, le sable doit rester dedans.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Éplucher environ 780 g de pommes de terre à chair ferme achetées en robe pour obtenir les 625 g de chair utile, puis les tailler en gros quartiers d''environ trois centimètres qui tiendront au mijotage sans se déliter.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Chauffer l''huile d''olive dans une cocotte large, y laisser fondre l''oignon émincé finement et les brins de fenouil ciselés pendant huit minutes à feu doux, sans jamais chercher la coloration, puis ajouter l''ail écrasé et prolonger une minute le temps qu''il libère son parfum.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Incorporer la tomate râpée et le concentré, remonter un peu le feu et laisser compoter cinq minutes en remuant, jusqu''à ce que le jus épaississe et que le mordant acide de la tomate s''arrondisse.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Mouiller avec les 800 ml de fond de poisson et le jus de moules filtré, ajouter le laurier, le thym, le zeste de citron et le poivre, puis amener doucement à frémissement — un bouillon marin qui bout à gros bouillons devient trouble et amer.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Délayer le safran dans une petite louche de bouillon chaud pour qu''il diffuse sa couleur, le reverser dans la cocotte, ajouter les quartiers de pomme de terre et laisser cuire vingt à vingt-cinq minutes à tout petits frémissements, jusqu''à ce que la pointe d''un couteau traverse un morceau sans résistance.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 8, 'Couper le feu, remettre la chair de moule et les coquilles réservées, couvrir deux minutes pour les réchauffer sans les raidir. Goûter seulement à cet instant avant de saler, la base marine étant déjà salée, puis servir en assiette creuse en répartissant bouillon, pommes de terre et coquillages.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'SRC-033', 'recipe_family', 'Bouillabaisse',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'SRC-033', 'missing_required_count', v_missing), 'open');
  END IF;

  WITH axis AS (
    INSERT INTO culinary.recipe_variation_axes
      (recipe_family_id, name, selection_mode, required)
    VALUES (v_family, 'Variante culinaire', 'single', false)
    RETURNING id
  )
  INSERT INTO culinary.recipe_variation_options
    (variation_axis_id, name, confidence_level, status)
  SELECT axis.id, variant.name, 'B', 'candidate'
  FROM axis
  CROSS JOIN unnest(ARRAY['Version pêcheur : remplacer une partie des moules par des filets de poisson de roche déposés sur le bouillon et pochés hors du feu cinq minutes.','Service à la marseillaise : passer le bouillon et le servir à part, brûlant, avec des croûtons frottés d''ail, la garniture étant présentée à côté sur un plat creux.','Sans alcool : supprimer le vin blanc, ouvrir les moules dans un fond d''eau et rattraper la vivacité par un trait de jus de citron au moment de servir.']::text[]) AS variant(name);

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_validation', 5,
     ARRAY['source_backed_variant_needs_test'], '{"recipe_code":"SRC-033","variants":["Version pêcheur : remplacer une partie des moules par des filets de poisson de roche déposés sur le bouillon et pochés hors du feu cinq minutes.","Service à la marseillaise : passer le bouillon et le servir à part, brûlant, avec des croûtons frottés d''ail, la garniture étant présentée à côté sur un plat creux.","Sans alcool : supprimer le vin blanc, ouvrir les moules dans un fond d''eau et rattraper la vivacité par un trait de jus de citron au moment de servir."]}'::jsonb, 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:SRC-033', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('bfc3fabb49002024a1e431a3dcf889e4'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"warm_aromatic","scores":{"sweet":1,"salty":4,"acidic":2,"bitter":1,"umami":4,"heat":0,"pungency":2,"richness":2,"freshness":2,"intensity":4},"dominant_flavors":["iodé","safran","tomate cuite","ail"],"aroma_families":["marine","épice safranée","anisée","agrume"],"target_textures":["bouillon fluide et soyeux","pomme de terre fondante","chair de moule tendre"],"signature_ingredients":["Sauce poisson","Moule commune crue","Safran"],"identity_guardrails":["Sans safran, le bouillon perd sa robe orangée et son parfum : ce n''est plus une bouillabaisse mais une soupe de pommes de terre à la tomate.","Sans base marine — fond de poisson et coquillages — il ne reste qu''un ragoût de légumes ; l''iode est la colonne vertébrale du plat.","La garniture reste strictement marine et provençale : ni viande, ni condiment asiatique, quoi qu''en disent les relevés d''ingrédients aberrants.","Le bouillon ne doit jamais bouillir franchement, sous peine de troubler et de durcir les coquillages."]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '349fe655173914ccfd579fd2e6d29046' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;
DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Calamars à l''armoricaine', 'calamars a l armoricaine', 'France', 'France',
     'meal', 'plat mijoté', 'named_traditional_dish', 'savory_tomato',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
