  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'La veille, noyez les haricots blancs secs sous trois fois leur volume d''eau froide et laissez-les gonfler douze heures au frais ; le lendemain, jetez cette eau et rincez-les.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Demandez au boucher une poitrine d''environ 250 g avec sa couenne : détachée, la couenne servira à tapisser le plat, et il reste les 200 g de chair de la liste. Taillez cette chair en gros lardons, démarrez-les à l''eau froide, comptez cinq minutes à partir du frémissement, égouttez.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Mettez les haricots égouttés dans une grande cocotte avec la carotte en tronçons, la moitié de l''oignon piquée des clous de girofle, le thym, le laurier et la couenne roulée. Couvrez d''eau froide sans saler, écumez dès les premiers bouillons, puis maintenez un frémissement paresseux cinquante minutes. Les grains doivent rester entiers sous la dent.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Pendant ce temps, sortez les cuisses de canard confites de leur graisse : comptez six cuisses, soit à peu près 1,2 kg pesées à l''achat avec l''os et la graisse figée, pour obtenir les 800 g de chair annoncés. Grattez la graisse excédentaire, réservez-en deux cuillerées, et détachez les hauts de cuisse des pilons.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Faites fondre la graisse de confit réservée dans une large sauteuse. Colorez-y la saucisse de Toulouse enroulée en escargot, puis les lardons de poitrine, enfin le porc haché roulé en petites boulettes serrées. Cherchez une belle teinte ambrée, jamais une croûte brûlée, et débarrassez au fur et à mesure.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Dans la même graisse, jetez le reste d''oignon émincé et les deux tiers de l''ail écrasé. Quand l''oignon devient translucide, incorporez la tomate râpée et le concentré, laissez compoter dix minutes en grattant les sucs, puis mouillez de deux louches du bouillon de haricots.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Égouttez les haricots en gardant tout leur bouillon, retirez l''oignon clouté, la carotte et les feuilles de laurier. Mélangez-les à la fondue de tomate, puis assaisonnez ici seulement : les 12 g de sel fin pour huit parts suffisent, car poitrine, saucisses et confit apportent déjà beaucoup de sel. Poivrez généreusement.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 8, 'Frottez d''ail cru l''intérieur d''une cassole ou d''une cocotte en terre, couchez la couenne au fond gras contre la paroi, puis montez par couches alternées : haricots, viandes rissolées, morceaux de confit, éventuellement les rondelles épaisses de saucisse de Montbéliard, et terminez par une couche de haricots. Versez du bouillon jusqu''à effleurer la surface.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 9, 'Enfournez à 150 °C pour trois heures à découvert. Toutes les quarante minutes, crevez la croûte formée en surface avec le dos d''une cuillère et rajoutez une louche de bouillon chaud si le dessus s''assèche : ce geste répété est ce qui donne au plat son liant.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 10, 'Dans la dernière demi-heure, poudrez la chapelure de blé sur toute la surface et montez le four à 170 °C jusqu''à obtenir une croûte dorée et cassante. Sortez le plat et laissez-le se détendre vingt minutes avant de servir à la louche, dans des assiettes chaudes.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'SRC-036', 'recipe_family', 'Cassoulet',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'SRC-036', 'missing_required_count', v_missing), 'open');
  END IF;

  WITH axis AS (
    INSERT INTO culinary.recipe_variation_axes
      (recipe_family_id, name, selection_mode, required)
    VALUES (v_family, 'Variante culinaire', 'single', false)
    RETURNING id
  )
  INSERT INTO culinary.recipe_variation_options
    (variation_axis_id, name, confidence_level, status)
  SELECT axis.id, variant.name, 'B', 'candidate'
  FROM axis
  CROSS JOIN unnest(ARRAY['Version de Castelnaudary : uniquement porc, couenne et confit de canard, sans agneau ni tomate.','Version sans chapelure : on se contente d''enfoncer sept fois la croûte de haricots au cours de la cuisson au four.','Ajout de Saucisse de Montbéliard pour une note fumée, à la place ou en complément de la saucisse de Toulouse.','Cuisson en deux jours : trois heures de four la veille, refroidissement complet, puis une heure de reprise avant le service.']::text[]) AS variant(name);

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_validation', 5,
     ARRAY['source_backed_variant_needs_test'], '{"recipe_code":"SRC-036","variants":["Version de Castelnaudary : uniquement porc, couenne et confit de canard, sans agneau ni tomate.","Version sans chapelure : on se contente d''enfoncer sept fois la croûte de haricots au cours de la cuisson au four.","Ajout de Saucisse de Montbéliard pour une note fumée, à la place ou en complément de la saucisse de Toulouse.","Cuisson en deux jours : trois heures de four la veille, refroidissement complet, puis une heure de reprise avant le service."]}'::jsonb, 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:SRC-036', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('d71d1d138b469383735fee532e9912e2'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"warm_aromatic","scores":{"sweet":1,"salty":3,"acidic":1,"bitter":0,"umami":4,"heat":0,"pungency":2,"richness":5,"freshness":0,"intensity":4},"dominant_flavors":["gras de canard confit","porc rissolé","haricot fondant","ail cuit"],"aroma_families":["carné rôti","herbacé sec","aillé","graisse fondue"],"target_textures":["haricot fondant à peau intacte","croûte de chapelure cassante","viande confite qui s''effiloche"],"signature_ingredients":["Haricot blanc sec","Confit de canard cuit","Saucisse de Toulouse crue","Poitrine de porc crue"],"identity_guardrails":["Sans haricot blanc sec trempé et cuit à part dans un bouillon de couenne, ce n''est plus un cassoulet mais un ragoût de charcuterie.","Le confit de canard et la saucisse de Toulouse portent l''identité toulousaine du plat : les remplacer par une viande maigre le fait basculer ailleurs.","La cuisson longue au four à découvert, avec la croûte enfoncée plusieurs fois, est constitutive : un mijotage à couvert sur le feu donne un autre plat.","Aucun liant à la farine ni crème : l''onctuosité vient de l''amidon des haricots et de la graisse de confit."]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '349fe655173914ccfd579fd2e6d29046' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;
DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Céleri rémoulade', 'celeri remoulade', 'France', 'France',
     'meal', 'entrée froide', 'named_traditional_dish', 'creamy_savory',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation)
  SELECT
    v_family, 3, 'Céleri rémoulade', 'Céleri branche en julienne avec une sauce rémoulade à la moutarde, jaune d''œuf et yaourt', ds.id, 'SRC-037',
    'Myko', 'editorial', 4, 25, 0, 'facile',
    NULL, NULL,
    'B', 'candidate', '741159e7b559260e5cf32c6b8e5a8cda',
    '{"sweet":1,"salty":2,"acidic":3,"bitter":1,"umami":1,"heat":0,"pungency":3,"richness":4,"freshness":3,"intensity":3}'::jsonb, ARRAY['moutarde','citron','céleri']::text[],
    ARRAY['moutardé','agrume','herbacé']::text[], ARRAY['croquant','crémeux']::text[],
    ARRAY['Céleri branche cru','Moutarde de Dijon','Jus de citron frais']::text[], ARRAY['Le céleri reste cru et taillé en filaments : cuit ou réduit en purée, ce n''est plus une rémoulade.','La moutarde doit rester perceptible dans l''émulsion, c''est elle qui donne son mordant au nom du plat.','L''acidité du citron est structurelle, elle empêche l''oxydation et équilibre le gras de la sauce ; la supprimer donne une salade grise et lourde.']::text[],
    ARRAY['émulsion','marinade']::text[], ARRAY['Version allégée sans jaune d''œuf ni huile : yaourt nature, moutarde et jus de citron simplement fouettés ensemble.','Céleri plongé trente secondes dans l''eau bouillante salée puis rafraîchi à l''eau glacée, pour des filaments plus tendres et moins piquants.','Sauce relevée de câpres rincées et grossièrement hachées, comme dans la variante marmiton.','Bâtonnets de pomme acidulée mêlés à la masse plutôt que posés dessus, pour une rémoulade franchement fruitée.']::text[], ARRAY['œuf','lait','moutarde']::text[],
    'Se conserve 48 heures au réfrigérateur à 4 °C dans un contenant hermétique ; le céleri continue de rendre de l''eau, égoutter et remuer avant de servir. Ne supporte pas la congélation : l''émulsion tranche au décongélation et les filaments deviennent mous et spongieux.', false, '[]'::jsonb,
    NULL, '{}'::jsonb
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation
  RETURNING id INTO v_version;

  DELETE FROM quality.review_tasks rt
  USING culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version
    AND rt.entity_type = 'recipe_ingredient_requirement'
    AND rt.entity_id = req.id;
  DELETE FROM quality.review_tasks WHERE entity_type = 'recipe_version' AND entity_id = v_version;
  DELETE FROM culinary.recipe_steps WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_ingredient_requirements WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_instruction_branches WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_components WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_variation_axes WHERE recipe_family_id = v_family;

  INSERT INTO culinary.recipe_components (recipe_version_id, name, component_role, position)
  VALUES (v_version, 'plat', 'main', 1)
  RETURNING id INTO v_component;

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'celeri branche cru' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Céleri branche cru', 600, 'g', 'required',
     'légume principal', false, 1);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
