  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Émietter le pain de campagne dans un bol et l''arroser du lait entier à peine tiédi. La mie doit avoir bu tout le liquide le temps que le reste se prépare ; on l''essorera ensuite entre les paumes.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Partir d''un chou vert d''environ 1,6 kg tel qu''on l''achète chez le primeur. Ôter les feuilles extérieures fanées ou tachées et raccourcir le trognon au couteau : il reste à peu près les 1,2 kg de chou réellement comestible annoncés dans la liste.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Immerger la tête entière dans un grand faitout d''eau salée maintenue à petits frémissements et compter un quart d''heure. Sortir le chou, le poser à l''envers dans une passoire et le laisser tiédir sans jamais l''écraser, sous peine de déchirer les feuilles.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Éplucher les légumes en tenant compte des pertes : comptez environ 300 g de carottes et 240 g d''oignons au poids d''achat pour retrouver les poids pelés de la liste. Tailler les carottes en rondelles épaisses, émincer finement la moitié des oignons et hacher l''autre moitié.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Détailler la poitrine de porc au couteau en très petits dés, puis la réunir dans un grand saladier avec le bœuf haché, le porc haché, l''ail écrasé, le persil ciselé, l''oignon haché, les œufs battus et la mie pressée.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Saler, poivrer, puis malaxer la farce à pleines mains deux bonnes minutes, jusqu''à ce qu''elle devienne homogène et légèrement collante au creux de la paume.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Écarter une à une les feuilles du chou tiédi, en progressant de l''extérieur vers le centre, jusqu''à dégager complètement le cœur. Détacher ce cœur, le hacher menu et le mêler à la farce, qui gagne ainsi le goût du chou.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 8, 'Loger une grosse poignée de farce dans le creux laissé par le cœur, puis remonter les rangs de feuilles en glissant un peu de farce à chaque étage et en rabattant les feuilles au fur et à mesure, de façon à reformer une boule bien pleine et régulière.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 9, 'Croiser deux longueurs de ficelle de cuisine sur le plan de travail, asseoir le chou reconstitué au centre et nouer les brins sur le dessus, assez serré pour que rien ne s''ouvre pendant les deux heures de cuisson.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 10, 'Beurrer largement le fond d''une cocotte, y étaler les lamelles d''oignon et les rondelles de carotte en lit régulier, poser le chou dessus, puis verser le bouillon de volaille et la tomate râpée le long des parois pour ne pas délaver le dessus.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 11, 'Amener à frémissement à découvert, couvrir, puis tenir le feu au plus bas pendant deux heures. Arroser le dessus du chou avec le jus toutes les demi-heures et vérifier que rien n''accroche au fond.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 12, 'Laisser reposer dix minutes hors du feu, couper les ficelles aux ciseaux, faire glisser le chou sur un plat creux et le partager en quartiers au grand couteau, chaque part nappée du jus de cuisson.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'SRC-038', 'recipe_family', 'Chou farci',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'SRC-038', 'missing_required_count', v_missing), 'open');
  END IF;

  WITH axis AS (
    INSERT INTO culinary.recipe_variation_axes
      (recipe_family_id, name, selection_mode, required)
    VALUES (v_family, 'Variante culinaire', 'single', false)
    RETURNING id
  )
  INSERT INTO culinary.recipe_variation_options
    (variation_axis_id, name, confidence_level, status)
  SELECT axis.id, variant.name, 'B', 'candidate'
  FROM axis
  CROSS JOIN unnest(ARRAY['Chou farci en petits paquets : une boulette de farce par feuille blanchie, refermée en aumônière et mijotée dans la tomate râpée','Version dombiste : la moitié de la viande est remplacée par de la chair de brochet crue, pour une farce plus fine et plus pâle','Montage en gratin : couches alternées de feuilles et de farce dans un plat, nappées de tomate râpée et cuites une heure à 180 °C','Au chou blanc frais quand le chou vert manque : les feuilles sont plus serrées, allonger le blanchiment de cinq minutes']::text[]) AS variant(name);

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_validation', 5,
     ARRAY['source_backed_variant_needs_test'], '{"recipe_code":"SRC-038","variants":["Chou farci en petits paquets : une boulette de farce par feuille blanchie, refermée en aumônière et mijotée dans la tomate râpée","Version dombiste : la moitié de la viande est remplacée par de la chair de brochet crue, pour une farce plus fine et plus pâle","Montage en gratin : couches alternées de feuilles et de farce dans un plat, nappées de tomate râpée et cuites une heure à 180 °C","Au chou blanc frais quand le chou vert manque : les feuilles sont plus serrées, allonger le blanchiment de cinq minutes"]}'::jsonb, 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:SRC-038', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('0f5c4e43c7002b6a8e2e4929291f6d53'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"warm_aromatic","scores":{"sweet":2,"salty":3,"acidic":2,"bitter":1,"umami":4,"heat":0,"pungency":1,"richness":4,"freshness":1,"intensity":3},"dominant_flavors":["viande braisée","chou fondant","bouillon de volaille","tomate cuite"],"aroma_families":["végétal cuit","gras animal","aromates verts"],"target_textures":["feuilles fondantes","farce moelleuse et serrée","jus court et nappant"],"signature_ingredients":["Chou vert frais","Bœuf haché cru 15 % MG","Porc haché cru","Poitrine de porc crue"],"identity_guardrails":["Les feuilles de chou vert entières doivent envelopper la farce et le chou être reconstitué en boule : émincé et mélangé à la viande, ce n''est plus un chou farci mais une potée","La farce reste une viande hachée grasse liée à la mie de pain et à l''œuf ; sans le gras de la poitrine de porc elle se dessèche et le plat perd son moelleux","La cuisson est un mijotage long à couvert dans un mouillement court, pas un rôtissage à sec"]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '349fe655173914ccfd579fd2e6d29046' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;
DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Coquilles Saint-Jacques', 'coquilles saint jacques', 'France', 'France',
     'meal', 'gratin', 'named_traditional_dish', 'creamy_savory',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation)
  SELECT
    v_family, 3, 'Coquilles Saint-Jacques', 'Noix de Saint-Jacques dans leur coquille, gratinées avec sauce crème et chapelure', ds.id, 'SRC-039',
    'Myko', 'editorial', 4, 30, 25, 'moyenne',
    NULL, NULL,
    'B', 'candidate', '68e3c27c42431f4ff70faa183837b942',
    '{"sweet":2,"salty":2,"acidic":2,"bitter":0,"umami":3,"heat":0,"pungency":1,"richness":4,"freshness":1,"intensity":3}'::jsonb, ARRAY['iodé','crémeux beurré','vin blanc réduit','échalote fondue']::text[],
    ARRAY['marin','lacté','alliacé','grillé']::text[], ARRAY['chair nacrée et moelleuse','sauce nappante','croûte de chapelure croustillante']::text[],
    ARRAY['Noix de Saint-Jacques crue','Crème fraîche liquide entière','Vin blanc sec','Chapelure de blé']::text[], ARRAY['Sans noix de Saint-Jacques, ce n''est pas le plat : un autre poisson blanc en fait une simple coquille de poisson à la crème.','Les noix se saisissent très vite, une minute par face au plus : au-delà elles se rétractent et deviennent caoutchouteuses.','Le poids déclaré est celui des noix décoquillées — une coquille entière n''en donne qu''une trentaine de grammes.']::text[],
    ARRAY['saisie','réduction','déglaçage','gratinage']::text[], ARRAY['Fond de fondue de poireaux : blancs de poireaux émincés fondus 20 minutes au beurre sous la sauce, comme sur deux pages de 750g.com.','Version aux morilles réhydratées poêlées à l''ail, avec un appareil crème-œufs versé directement sur la chair avant chapelure.','Coquilles refermées et scellées d''un boudin de pâte à luter, cuites 10 minutes à 200 °C et ouvertes au couteau à table.','Sauce Mornay au gruyère râpé et à la muscade, montée au lait, servie en petits poêlons individuels.','Poêlée simple flambée à l''alcool de grain, crème et persil, dressée sur riz ou pommes de terre tièdes.']::text[], ARRAY['mollusques','poisson','lait','œuf','gluten','sulfites']::text[],
    'Monté mais non enfourné, le plat attend jusqu''à 12 h à 4 °C sous film. Cuit, il se garde 24 h au réfrigérateur et se réchauffe 6 à 7 minutes à 180 °C, jamais au micro-ondes. La chair crue parée ne dépasse pas 24 h posée sur un lit de glace. Congélation : acceptable pour la chair crue étalée à plat et bien épongée (2 mois), déconseillée pour le plat sauce comprise — la crème liée aux jaunes tranche au réchauffage et la chair devient élastique.', false, '[]'::jsonb,
    NULL, '{}'::jsonb
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation
  RETURNING id INTO v_version;

  DELETE FROM quality.review_tasks rt
