  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Prévoir environ 3 kg de coquilles entières pour quatre, soit une bonne douzaine de pièces lourdes et bien closes : une fois décoquillées et parées, elles rendent les 500 g de chair de la liste, le reste étant coquille, manteau et viscères. Les brosser sous un filet d''eau froide sans jamais les laisser tremper.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Ouvrir chaque coquille en engageant une lame rigide contre la face plate, au niveau de la charnière, puis en rasant l''intérieur du couvercle pour trancher le muscle. Détacher la chair, ôter la frange grise et le petit nerf latéral, rincer très vite et éponger à fond. Mettre de côté huit coquilles creuses, brossées puis passées à l''eau bouillante une minute, qui serviront de plats.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Chauffer une poêle jusqu''à ce qu''elle fume légèrement, y verser l''huile d''olive et saisir la chair bien sèche 45 secondes par face, en deux fois pour ne pas encombrer la poêle. Elle doit rester nacrée à cœur. La débarrasser aussitôt sur une assiette froide et garder le jus rendu.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Ciseler les échalotes menu et les faire suer deux minutes dans 10 g de beurre sans les colorer. Mouiller avec le vin blanc, ajouter le jus rendu par la chair et laisser réduire à feu moyen jusqu''à ce qu''il ne reste qu''un fond sirupeux, environ la moitié du volume.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Dans une casserole à part, fondre 25 g de beurre, pluie de farine, remuer une minute à feu doux : le mélange doit mousser sans blondir. Verser la réduction passée au tamis puis la crème en trois fois, en fouettant. Laisser épaissir 5 minutes à petits bouillons jusqu''à ce que la sauce nappe le dos d''une cuillère.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Retirer du feu, attendre une minute, puis incorporer les jaunes d''œufs un par un au fouet — la sauce ne doit plus jamais bouillir, sous peine de grainer. Poivrer, ciseler le persil dedans, goûter et n''ajuster le sel qu''après : la réduction en apporte déjà beaucoup.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Trancher les grosses pièces de chair en deux dans l''épaisseur, les répartir dans les coquilles creuses posées sur une plaque, napper de sauce sans noyer, saupoudrer de chapelure et parsemer des 5 g de beurre restants en tout petits éclats.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 8, 'Enfourner dans le haut d''un four préchauffé à 210 °C pour 8 à 10 minutes, le temps que la chapelure prenne couleur. S''arrêter dès que la croûte est dorée : au-delà, la chair se rétracte et devient élastique. Servir immédiatement, les coquilles calées sur un lit de gros sel.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'SRC-039', 'recipe_family', 'Coquilles Saint-Jacques',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'SRC-039', 'missing_required_count', v_missing), 'open');
  END IF;

