  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:SRC-039', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('68e3c27c42431f4ff70faa183837b942'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"creamy_savory","scores":{"sweet":2,"salty":2,"acidic":2,"bitter":0,"umami":3,"heat":0,"pungency":1,"richness":4,"freshness":1,"intensity":3},"dominant_flavors":["iodé","crémeux beurré","vin blanc réduit","échalote fondue"],"aroma_families":["marin","lacté","alliacé","grillé"],"target_textures":["chair nacrée et moelleuse","sauce nappante","croûte de chapelure croustillante"],"signature_ingredients":["Noix de Saint-Jacques crue","Crème fraîche liquide entière","Vin blanc sec","Chapelure de blé"],"identity_guardrails":["Sans noix de Saint-Jacques, ce n''est pas le plat : un autre poisson blanc en fait une simple coquille de poisson à la crème.","Les noix se saisissent très vite, une minute par face au plus : au-delà elles se rétractent et deviennent caoutchouteuses.","Le poids déclaré est celui des noix décoquillées — une coquille entière n''en donne qu''une trentaine de grammes."]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '349fe655173914ccfd579fd2e6d29046' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;
DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Fenouil braisé', 'fenouil braise', 'France', 'France',
     'meal', 'légume braisé', 'domestic_standard', 'warm_aromatic',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation)
  SELECT
    v_family, 3, 'Fenouil braisé', 'Fenouil en quartiers saisi puis braisé au vin blanc et bouillon, acidulé au citron', ds.id, 'SRC-040',
    'Myko', 'editorial', 4, 15, 35, 'facile',
    NULL, NULL,
    'B', 'candidate', 'da533a1feae86a0d2d7b384811b8fe46',
    '{"sweet":3,"salty":2,"acidic":2,"bitter":1,"umami":1,"heat":0,"pungency":1,"richness":3,"freshness":2,"intensity":2}'::jsonb, ARRAY['anisé','citronné','sucré végétal']::text[],
    ARRAY['anisée','agrume','herbacée']::text[], ARRAY['fondant','légèrement confit','jus sirupeux']::text[],
    ARRAY['Fenouil frais','Vin blanc sec','Jus de citron frais']::text[], ARRAY['Le fenouil doit être braisé en quartiers gardant leur cœur : émincé finement, il devient une fondue de fenouil et perd l''identité du plat.','La cuisson se fait à couvert dans un liquide court puis réduit ; rôti à sec au four, le résultat n''est plus un braisé.','L''acidité du vin blanc et du citron est structurante : sans elle le plat vire au légume sucré et l''amertume du bulbe ressort.']::text[],
    ARRAY['saisie','déglaçage','mijotage','réduction']::text[], ARRAY['À la provençale : remplacer une partie de l''eau par du jus de tomate et ajouter une lanière de zeste d''orange dans le liquide de braisage.','Départ blanchi, façon 750g.com : plonger les demi-bulbes cinq minutes dans une eau bouillante salée et les égoutter avant de les colorer, pour un cœur encore plus fondant.','Sans alcool : supprimer le vin blanc sec, compenser par la même quantité d''eau et doubler le jus de citron frais en fin de réduction.','Tout à l''huile d''olive : retirer le beurre et monter à 40 g d''huile, pour une version maigre et une conservation plus longue au froid.']::text[], ARRAY['lait','sulfites']::text[],
    'Se conserve 3 jours au réfrigérateur à 4 °C, dans une boîte hermétique et baigné de son jus de braisage ; réchauffer doucement à couvert avec une cuillère d''eau. La congélation est déconseillée : les fibres du fenouil éclatent au dégel et le légume rend son eau, donnant une texture filandreuse et un jus délavé.', false, '[]'::jsonb,
    NULL, '{}'::jsonb
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation
  RETURNING id INTO v_version;

