    INSERT INTO culinary.recipe_variation_axes
      (recipe_family_id, name, selection_mode, required)
    VALUES (v_family, 'Variante culinaire', 'single', false)
    RETURNING id
  )
  INSERT INTO culinary.recipe_variation_options
    (variation_axis_id, name, confidence_level, status)
  SELECT axis.id, variant.name, 'B', 'candidate'
  FROM axis
  CROSS JOIN unnest(ARRAY['Version au bouillon, comme sur marmiton : remplacer le lait entier par du bouillon de volaille bien chaud pour une sauce plus légère, et ne garder la crème qu''en filet final.','Version au curry de chefsimon : fouetter une petite cuillerée de curry en poudre dans la béchamel juste avant de napper, en rallongeant d''un peu de lait si la sauce s''épaissit trop.','Version à l''oignon : faire blondir un oignon jaune finement émincé dans le beurre avant d''ajouter la farine, ce qui donne une sauce plus douce et plus sucrée.','Version croquante : parsemer une poignée de noix grossièrement concassées avec le fromage du dessus, à ajouter en fin de cuisson pour qu''elles ne brûlent pas.']::text[]) AS variant(name);

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_validation', 5,
     ARRAY['source_backed_variant_needs_test'], '{"recipe_code":"SRC-041","variants":["Version au bouillon, comme sur marmiton : remplacer le lait entier par du bouillon de volaille bien chaud pour une sauce plus légère, et ne garder la crème qu''en filet final.","Version au curry de chefsimon : fouetter une petite cuillerée de curry en poudre dans la béchamel juste avant de napper, en rallongeant d''un peu de lait si la sauce s''épaissit trop.","Version à l''oignon : faire blondir un oignon jaune finement émincé dans le beurre avant d''ajouter la farine, ce qui donne une sauce plus douce et plus sucrée.","Version croquante : parsemer une poignée de noix grossièrement concassées avec le fromage du dessus, à ajouter en fin de cuisson pour qu''elles ne brûlent pas."]}'::jsonb, 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:SRC-041', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('ab2324b94c8d06892e641985d87d5883'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"creamy_savory","scores":{"sweet":1,"salty":3,"acidic":0,"bitter":1,"umami":3,"heat":0,"pungency":1,"richness":4,"freshness":1,"intensity":3},"dominant_flavors":["lacté crémeux","fromage affiné","légume crucifère doux"],"aroma_families":["lacté","beurré","épices douces"],"target_textures":["bouquets fondants","sauce nappante","croûte gratinée"],"signature_ingredients":["Chou-fleur frais","Gruyère râpé","Lait entier"],"identity_guardrails":["Les bouquets de chou-fleur doivent rester entiers et identifiables sous la sauce : réduits en purée, le plat devient un flan de légume et non un gratin.","La sauce blanche liée au roux beurre-farine-lait est la colonne vertébrale du plat ; la remplacer par de la crème seule ou par un simple jus de cuisson en change la nature.","La couche de fromage gratinée en surface est obligatoire : sans croûte dorée, il ne reste qu''un chou-fleur à la béchamel."]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '349fe655173914ccfd579fd2e6d29046' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;
DO $recipe$
DECLARE
