  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Parer le chou : d''une pomme achetée entière d''environ 1,1 kg, jeter les feuilles extérieures fatiguées et creuser le trognon à la pointe du couteau, ce qui laisse à peu près 800 g de feuilles utilisables. Fendre en quartiers, dégager la côte centrale trop dure et rincer à grande eau.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Immerger les quartiers de chou dans un grand volume d''eau bouillante non salée, compter deux à trois minutes dès que l''ébullition repart, puis les cueillir à l''écumoire et les rafraîchir sous le robinet froid. Les laisser s''égoutter, côte vers le bas : ce passage arrondit l''amertume et rend le plat plus digeste.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Gratter les légumes-racines. Prévoir environ 600 g de carottes et 500 g de navets à l''achat pour obtenir respectivement 500 g et 400 g nets une fois épluchés et les bouts retirés. Débiter les carottes en gros tronçons de quatre centimètres, les navets en quartiers, de façon que tout cuise au même rythme.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Peler les oignons. En piquer un de tous les clous de girofle, en enfonçant chaque tête dans la chair jusqu''à ce qu''elle tienne seule ; couper l''autre en deux. Écraser les gousses d''ail d''un coup de paume, sans chercher à les peler complètement.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Coucher les saucisses de Morteau et de Montbéliard entières au fond d''une grande cocotte, sans jamais les piquer, et les recouvrir de trois bons doigts d''eau froide. Ajouter l''oignon clouté, l''oignon fendu et l''ail, puis monter tout doucement en température.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Dès que la surface frissonne, cueillir la mousse grise à la louche jusqu''à ce que le bouillon redevienne net. Maintenir ensuite un frémissement paresseux, couvercle posé de biais, pendant quarante-cinq minutes : une ébullition franche ferait éclater la peau des saucisses et troublerait le liquide. Ne rien saler à ce stade, la charcuterie fumée s''en charge.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Faire glisser carottes et navets dans le bouillon et laisser aller vingt-cinq minutes. Ajouter alors les quartiers de chou blanchis et les pommes de terre pelées — compter à peu près 750 g de tubercules achetés pour les 600 g de chair attendus — et poursuivre trente minutes, jusqu''à ce que la lame d''un couteau traverse une pomme de terre sans buter.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 8, 'Goûter le bouillon avant toute correction : selon la salaison des saucisses, les 10 g de sel fin prévus seront de trop ou tout juste nécessaires, alors les incorporer par petites pincées successives. Donner un tour de moulin de poivre noir moulu et couper le feu.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 9, 'Sortir les saucisses, les trancher en rondelles épaisses et les disposer au centre d''un plat creux bien chaud. Ranger les légumes autour par familles, mouiller de trois ou quatre louches de bouillon brûlant et servir aussitôt, le reste du bouillon en soupière à côté.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'SRC-050', 'recipe_family', 'Potée auvergnate',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'SRC-050', 'missing_required_count', v_missing), 'open');
  END IF;

  WITH axis AS (
    INSERT INTO culinary.recipe_variation_axes
      (recipe_family_id, name, selection_mode, required)
    VALUES (v_family, 'Variante culinaire', 'single', false)
    RETURNING id
  )
  INSERT INTO culinary.recipe_variation_options
    (variation_axis_id, name, confidence_level, status)
  SELECT axis.id, variant.name, 'B', 'candidate'
  FROM axis
  CROSS JOIN unnest(ARRAY['Potée au chou blanc : substituer un chou blanc au chou vert, en allongeant le blanchiment d''une minute car ses feuilles sont plus fermes.','Version charcutière complète : ajouter un jambonneau demi-sel dessalé deux heures à l''eau froide courante, mis à pocher une heure avant les saucisses.','Potée aux lentilles : verser 300 g de lentilles vertes avec les légumes-racines, en surveillant le niveau de bouillon qu''elles absorbent.','Service en deux temps, à la mode paysanne : le bouillon d''abord, versé sur des tranches de pain de campagne rassis, puis viandes et légumes en plat de résistance.','Accompagnement classique : un pot de moutarde forte et quelques cornichons posés sur la table.']::text[]) AS variant(name);

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_validation', 5,
     ARRAY['source_backed_variant_needs_test'], '{"recipe_code":"SRC-050","variants":["Potée au chou blanc : substituer un chou blanc au chou vert, en allongeant le blanchiment d''une minute car ses feuilles sont plus fermes.","Version charcutière complète : ajouter un jambonneau demi-sel dessalé deux heures à l''eau froide courante, mis à pocher une heure avant les saucisses.","Potée aux lentilles : verser 300 g de lentilles vertes avec les légumes-racines, en surveillant le niveau de bouillon qu''elles absorbent.","Service en deux temps, à la mode paysanne : le bouillon d''abord, versé sur des tranches de pain de campagne rassis, puis viandes et légumes en plat de résistance.","Accompagnement classique : un pot de moutarde forte et quelques cornichons posés sur la table."]}'::jsonb, 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:SRC-050', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('f2477562be0d458e1b72ee28ffcd93b7'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"warm_aromatic","scores":{"sweet":2,"salty":4,"acidic":0,"bitter":1,"umami":4,"heat":0,"pungency":1,"richness":3,"freshness":1,"intensity":3},"dominant_flavors":["porc fumé","chou braisé","bouillon salé","légume-racine sucré"],"aroma_families":["fumé","épices chaudes","végétal cuit"],"target_textures":["légumes fondants","pomme de terre farineuse","saucisse ferme et juteuse","bouillon clair"],"signature_ingredients":["Chou vert frais","Saucisse de Morteau","Saucisse de Montbéliard","Pomme de terre cuite"],"identity_guardrails":["Sans chou, ce n''est plus une potée : c''est lui qui structure le plat et parfume le bouillon en retour.","La charcuterie doit être fumée et pochée entière ; remplacer Morteau et Montbéliard par une viande fraîche non fumée efface le goût de cochonnaille qui fait le plat.","Les légumes cuisent dans le bouillon des viandes, jamais dans une eau neuve : c''est cet échange qui distingue la potée d''un simple pot-au-feu de légumes.","Pas de liaison ni de crème : le bouillon reste clair et se sert tel quel."]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '349fe655173914ccfd579fd2e6d29046' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;
DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Ratatouille', 'ratatouille', 'France', 'France',
     'meal', 'plat mijoté', 'named_traditional_dish', 'savory_tomato',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation)
  SELECT
    v_family, 3, 'Ratatouille', 'Compotée provençale d''aubergines, courgettes, poivrons et tomates à l''huile d''olive et à l''ail', ds.id, 'SRC-051',
    'Myko', 'editorial', 4, 30, 55, 'facile',
    NULL, NULL,
    'B', 'candidate', '58ce91cdb4c20575f9c10cf6d42505f1',
    '{"sweet":3,"salty":2,"acidic":2,"bitter":1,"umami":3,"heat":0,"pungency":1,"richness":3,"freshness":2,"intensity":3}'::jsonb, ARRAY['tomate cuite','poivron confit','ail','huile d''olive']::text[],
    ARRAY['herbacé méditerranéen','végétal grillé','aillé']::text[], ARRAY['dés fondants gardant leur forme','sauce courte et nappante']::text[],
    ARRAY['Aubergine fraîche','Courgette fraîche','Poivron rouge frais','Tomate fraîche mûre','Huile d''olive vierge extra']::text[], ARRAY['Les quatre légumes d''été — aubergine, courgette, poivron, tomate — sont indissociables : en retirer un fait sortir du plat.','L''huile d''olive est le seul corps gras admis ; beurre ou crème déplacent la recette vers une autre famille.','Aucun bouillon ni liquide ajouté : la liaison vient de l''eau et des sucs rendus par les légumes eux-mêmes.','Ni viande ni féculent dans la cocotte, sous peine de basculer vers un ragoût ou une poêlée composée.']::text[],
    ARRAY['saisie','mijotage','réduction']::text[], ARRAY['Version confite au four : les légumes sont empilés crus en couches dans une cocotte en fonte, salés et parfumés entre chaque étage, puis cuits couvercle fermé une heure à four moyen, sans une goutte d''eau ajoutée.','Version rapide en un seul récipient : tous les dés sont saisis ensemble à feu moyen puis mijotés vingt minutes, le résultat est plus fondu et moins distinct.','Ajout d''olives noires dénoyautées et tranchées dans les dix dernières minutes de cuisson.','Basilic ciselé jeté hors du feu au moment de servir, à la place ou en plus du thym.']::text[], ARRAY[]::text[],
    'Trois à quatre jours au réfrigérateur à 4 °C dans un contenant hermétique ; le goût se raffermit après une nuit de repos. Se congèle jusqu''à trois mois, mais les courgettes relâchent beaucoup d''eau à la décongélation : réchauffer à découvert pour faire évaporer le surplus avant de servir.', false, '[]'::jsonb,
    NULL, '{}'::jsonb
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation
  RETURNING id INTO v_version;

  DELETE FROM quality.review_tasks rt
